import { recursionDetectionMiddlewareOptions } from "@aws-sdk/core/dist-es/submodules/client/middleware-recursion-detection/configuration";
import { recursionDetectionMiddleware } from "@aws-sdk/core/dist-es/submodules/client/middleware-recursion-detection/recursionDetectionMiddleware";
export const getRecursionDetectionPlugin = (options) => ({
    applyToStack: (clientStack) => {
        clientStack.add(recursionDetectionMiddleware(), recursionDetectionMiddlewareOptions);
    },
});
